document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function e(n){return`${n.toFixed(1)}%`}function t(n,e,t,i="info"){return`\n      <div class="insight-card ${i}">\n        <h6>${n}</h6>\n        <div class="metric-value">${e}</div>\n        <div class="metric-subtitle">${t}</div>\n      </div>\n    `}const i=document.getElementById("marketing-form"),s=document.getElementById("marketing-result");i&&i.addEventListener("submit",function(i){i.preventDefault();const a=document.getElementById("agency-type").value,o=parseInt(document.getElementById("initial-employees").value),r=parseFloat(document.getElementById("software-cost").value),l=parseFloat(document.getElementById("office-cost").value),c=parseFloat(document.getElementById("marketing-capital").value),d=parseFloat(document.getElementById("avg-project-value").value),p=parseFloat(document.getElementById("profit-margin").value),v=parseFloat(document.getElementById("new-clients-month").value),u=parseFloat(document.getElementById("client-retention").value),m=parseFloat(document.getElementById("staff-costs").value),g=parseFloat(document.getElementById("software-monthly").value),y=parseFloat(document.getElementById("rent-costs").value),f=parseFloat(document.getElementById("other-expenses").value);if(o<=0||d<=0||p<=0||v<=0||u<=0)return s.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const w=r+l+c,$=v*u/2,h=v*u,b=$*d/u,k=12*b,I=p/100,E=k*I,B=m+g+y+f,A=12*B,F=E-A,M=F/12,P=F/k*100,x=w/F,C=F/w*100,S=k/o,D=F/o,L=d*(u/12),R={"smm-agency":"Social Media Agency","seo-agency":"SEO/SEM Agency","performance-agency":"Performance Agency","full-service":"Full-Service Digital Agency"};let O="info";F<0?O="warning":P>25&&(O="success");let T="info";C<30?T="warning":C>50&&(T="success");let j="info";S<6e4?j="warning":S>12e4&&(j="success");const N=(Math.min(h,2*$)*d/u*12-k)/k*100;s.innerHTML=`\n        <div class="business-plan-results">\n          <h3>📈 Marketing Agency Business Plan Analysis</h3>\n          <div class="agency-type-indicator">\n            <span class="agency-type-badge">${R[a]}</span>\n          </div>\n          \n          <div class="insight-cards">\n            ${t("💰 Total Investment",n(w),"Initial capital required","info")}\n            ${t("📈 Monthly Profit",n(M),`Net margin: ${e(P)}`,O)}\n            ${t("⏱️ Payback Period",`${x.toFixed(1)} years`,`ROI: ${e(C)}`,x<=2?"success":"warning")}\n            ${t("👥 Active Clients",`${$.toFixed(0)} clients`,"Average client base","info")}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Software & tools setup</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Office & equipment</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & working capital</span>\n                  <span>${n(c)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(w)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Annual Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Monthly revenue (${$.toFixed(0)} clients)</span>\n                  <span>${n(b)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Annual revenue</span>\n                  <span>${n(k)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Gross profit (${e(p)} margin)</span>\n                  <span>${n(E)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Annual Revenue</strong></span>\n                  <span><strong>${n(k)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Team payroll (${o} employees)</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Software, tools & subscriptions</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Office rent</span>\n                  <span>${n(y)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & other expenses</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(B)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>📊 Client Efficiency</h6>\n              <div class="metric-subtitle">\n                Average project value: <strong>${n(d)}</strong><br>\n                Client lifetime value: <strong>${n(L)}</strong><br>\n                New clients/month: <strong>${v} clients</strong>\n              </div>\n            </div>\n            <div class="insight-card ${S>8e4?"success":"info"}">\n              <h6>👨‍💼 Team Productivity</h6>\n              <div class="metric-subtitle">\n                Revenue per employee: <strong>${n(S)}/year</strong><br>\n                Profit per employee: <strong>${n(D)}/year</strong><br>\n                Average salary: <strong>${n(m/o)}/month</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${M>0?"success":"warning"}">\n              <h6>💰 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual net profit: <strong>${n(F)}</strong><br>\n                Weekly profit: <strong>${n(F/52)}</strong><br>\n                Client retention: <strong>${u} months</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>🎯 Growth Potential</h6>\n              <div class="metric-subtitle">\n                3-year potential: <strong>+${e(N)}</strong><br>\n                +2 clients/month: <strong>+${n(24*d)}/year</strong><br>\n                +10% margin increase: <strong>+${n(.1*k)}/year</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${P<20?"<li>⚠️ Low profitability. Consider increasing prices or reducing costs.</li>":""}\n              ${S<8e4?"<li>📍 Low productivity. Improve team efficiency or increase pricing.</li>":""}\n              ${x>3?"<li>⏰ Long payback period. Optimize startup costs or increase client base.</li>":""}\n              ${$<10?"<li>📈 Few clients. Intensify marketing and sales efforts.</li>":""}\n              ${u<9?"<li>🔄 Low retention. Improve service quality and customer support.</li>":""}\n              ${P>30?"<li>🎉 Excellent profitability! Consider team expansion and new services.</li>":""}\n              <li>🏆 Specialize in profitable niches: e-commerce, B2B, fintech, healthcare.</li>\n              <li>📊 Implement CRM system for client and project management.</li>\n              <li>🤖 Automate routine processes: reporting, social media, email campaigns.</li>\n              <li>⭐ Build case studies and portfolio to attract new clients.</li>\n              <li>💡 Introduce new services: marketing analytics, automation, AI tools.</li>\n              <li>📈 Develop long-term retainer contracts for stable revenue.</li>\n              <li>🎯 Invest in team training for new tools and technologies.</li>\n              <li>🌐 Build partner network with other agencies and freelancers.</li>\n              <li>📱 Develop proprietary digital products: courses, tools, consultations.</li>\n              <li>💰 Implement KPI system and incentives for productivity improvement.</li>\n              <li>📈 Consider white-label partnerships to expand service offerings.</li>\n              <li>🎨 Invest in brand building and thought leadership content.</li>\n              <li>📊 Use data analytics to demonstrate ROI to clients.</li>\n              <li>🤝 Build strategic partnerships with complementary service providers.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.marketingBusinessData={"Agency Type":R[a],"Number of Employees":o,"Total Investment ($)":w,"Annual Revenue ($)":k,"Gross Profit ($)":E,"Annual Expenses ($)":A,"Annual Net Profit ($)":F,"Monthly Profit ($)":M,"Gross Margin (%)":p,"Net Margin (%)":P,"Annual ROI (%)":C,"Payback Period (years)":x,"Revenue per Employee ($)":S,"Profit per Employee ($)":D,"Average Project Value ($)":d,"Active Clients":$,"New Clients/Month":v,"Client Retention (months)":u,"Client Lifetime Value ($)":L}}),window.downloadCSV=function(){if(!window.marketingBusinessData)return;const n=Object.entries(window.marketingBusinessData).map(([n,e])=>`"${n}","${"number"==typeof e?e.toFixed(2):e}"`).join("\n"),e=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),t=document.createElement("a");t.href=URL.createObjectURL(e),t.download="marketing-agency-business-plan.csv",t.click()}});